/**
 * 酒馆联机脚本
 * 全屏房间模式：玩家本地候选回复，房主导演模型整合，最终楼层同步。
 */
import { teleportStyle } from '@util/script';
import App from './App.vue';
$(() => {
    const pinia = createPinia();
    const parentDoc = window.parent.document;
    let app = null;
    let iframeEl = null;
    let styleDestroy = null;
    function openOnlineRoom() {
        if (app && iframeEl) {
            iframeEl.style.display = '';
            return;
        }
        const iframe = document.createElement('iframe');
        iframe.setAttribute('script_id', getScriptId());
        iframe.setAttribute('frameborder', '0');
        iframe.style.cssText = [
            'position:fixed',
            'inset:0',
            'width:100vw',
            'height:100vh',
            'z-index:99999',
            'border:none',
            'background:#10151f',
        ].join(';');
        iframe.addEventListener('load', () => {
            const iframeDoc = iframe.contentDocument;
            if (!iframeDoc)
                return;
            const { destroy } = teleportStyle(iframeDoc.head);
            styleDestroy = destroy;
            app = createApp(App, { onExit: closeOnlineRoom, onMinimize: minimizeOnlineRoom }).use(pinia);
            app.mount(iframeDoc.body);
        });
        parentDoc.body.appendChild(iframe);
        iframeEl = iframe;
    }
    function minimizeOnlineRoom() {
        if (iframeEl) {
            iframeEl.style.display = 'none';
        }
    }
    function closeOnlineRoom() {
        app?.unmount();
        app = null;
        styleDestroy?.();
        styleDestroy = null;
        iframeEl?.remove();
        iframeEl = null;
    }
    replaceScriptButtons([{ name: '打开联机房间', visible: true }]);
    eventOn(getButtonEvent('打开联机房间'), openOnlineRoom);
    $(window).on('pagehide', closeOnlineRoom);
});
