/**
 * 联机核心 Pinia Store
 * 管理所有联机状态、SSE 连接、业务操作
 */
import { applyTrimRules, clearAuthToken, readLocalSettings, saveLocalSettings, setAuthToken, } from '../types';
import { createRoom, fetchMe, fetchRoomState, fetchRooms, finalizeRound, joinRoom, leaveRoom, loginWithPassword, rerollRound, sendRoomChat, startRound, submitCandidate, submitRoundInput, toggleReady, updateRoundStream, } from '../api';
import { buildRoundUserMessage, captureCurrentCharacter, captureCurrentTavernApi, fetchDirectorModels, generateCandidate, generateSummary, getCurrentPresetNameSafe, insertFinalizedRound, runDirectorIntegration, syncCustomOpening, } from '../tavern';
import { roomSSE } from '../sse';
const STREAM_PUSH_INTERVAL_MS = 1500;
const FALLBACK_POLL_INTERVAL_MS = 10_000;
export const useOnlineStore = defineStore('online', () => {
    // ─── 状态 ───
    const view = ref('lobby');
    const user = ref(null);
    const rooms = ref([]);
    const roomState = ref(null);
    const selectedRoom = ref(null);
    const busy = ref(false);
    const authReady = ref(false);
    const loginForm = reactive({ username: '', password: '' });
    const joinForm = reactive({ roomId: '', password: '' });
    const roomPasswords = reactive({});
    const chatText = ref('');
    const roundMessage = ref('');
    const joinCharacterName = ref('');
    const joinCharacterPersona = ref('');
    const candidateBusy = ref(false);
    const integrationBusy = ref(false);
    const directorStream = ref('');
    const summaryCounter = ref(0);
    const directorModels = ref([]);
    const directorModelHint = ref('');
    const directorModelBusy = ref(false);
    const localSettings = ref(readLocalSettings());
    const requiredAssetsText = ref('');
    const sseStatus = ref('disconnected');
    const unsyncedRounds = ref([]);
    const createForm = reactive({
        title: '',
        visibility: 'public',
        password: '',
        character_name: '',
        character_summary: '',
        character_opening: '',
        custom_opening: '',
        character_card_link: '',
        preset_name: '',
        per_player_words: 1000,
        per_player_min_words: 700,
        per_player_max_words: 1000,
        candidate_timeout_seconds: 120,
        erase_on_close: true,
        host_character_name: '',
        host_character_persona: '',
    });
    let fallbackTimer;
    // ─── 计算属性 ───
    const isHost = computed(() => {
        return !!roomState.value && !!user.value && roomState.value.room.host_user_id === user.value.id;
    });
    const activeRound = computed(() => roomState.value?.active_round || null);
    const myInput = computed(() => {
        const round = activeRound.value;
        if (!round || !user.value)
            return null;
        return round.inputs.find(input => input.user_id === user.value.id) || null;
    });
    const allReady = computed(() => {
        if (!roomState.value || !user.value)
            return false;
        const members = roomState.value.members;
        return members.every(m => m.user_id === roomState.value.room.host_user_id || m.ready);
    });
    const submittedCount = computed(() => activeRound.value?.inputs.length || 0);
    const readyCount = computed(() => activeRound.value?.inputs.filter(input => input.status === 'candidate_ready').length || 0);
    const pendingCandidateCount = computed(() => Math.max(0, submittedCount.value - readyCount.value));
    const visibleDirectorStream = computed(() => {
        const raw = directorStream.value || activeRound.value?.assistant_message || '';
        return applyTrimRules(raw, localSettings.value.trimRules);
    });
    const canSubmitTurn = computed(() => !!activeRound.value && activeRound.value.status === 'collecting' &&
        !candidateBusy.value && !myInput.value && !!roundMessage.value.trim());
    const canRetryCandidate = computed(() => !!activeRound.value && activeRound.value.status === 'collecting' &&
        !candidateBusy.value && !!myInput.value && myInput.value.status !== 'candidate_ready');
    const canHostIntegrate = computed(() => !!activeRound.value && ['collecting', 'integrating'].includes(activeRound.value.status) &&
        activeRound.value.inputs.length > 0 && !integrationBusy.value);
    const roomTargetWords = computed(() => {
        if (!roomState.value)
            return '';
        const room = roomState.value.room;
        const minW = Math.min(8000, Math.max(100, room.member_count * (room.per_player_min_words || 700)));
        const maxW = Math.min(8000, Math.max(minW, room.member_count * (room.per_player_max_words || 1000)));
        return `${minW}~${maxW}`;
    });
    /** 当前回合状态引导文本 */
    const statusBannerText = computed(() => {
        if (!roomState.value)
            return '';
        const round = activeRound.value;
        if (!round)
            return '等待房主开启新一轮';
        if (round.status === 'integrating')
            return '导演正在整合所有发言...';
        if (myInput.value) {
            if (candidateBusy.value)
                return '正在生成你的候选回复...';
            if (myInput.value.status === 'candidate_ready')
                return '你的候选已完成，等待其他玩家或房主整合';
            return '发言已提交，候选待生成';
        }
        return '本轮发言收集中，请输入并提交你的发言';
    });
    // ─── Watchers ───
    watch(localSettings, value => saveLocalSettings(value), { deep: true });
    watch(() => localSettings.value.director.source, source => {
        if (source === 'deepseek') {
            if (!localSettings.value.director.apiurl) {
                localSettings.value.director.apiurl = 'https://api.deepseek.com/v1';
            }
            setDirectorModelsInternal(['deepseek-chat', 'deepseek-reasoner', 'deepseek-coder']);
        }
    });
    // ─── 错误处理 ───
    function setError(error) {
        const msg = error instanceof Error ? error.message : String(error);
        if (msg)
            toastr.error(msg);
    }
    // ─── 认证 ───
    async function loadMe() {
        try {
            user.value = await fetchMe();
        }
        catch {
            user.value = null;
        }
    }
    async function doLogin() {
        if (!loginForm.username.trim() || !loginForm.password) {
            setError('请输入用户名和密码');
            return;
        }
        busy.value = true;
        try {
            const result = await loginWithPassword(loginForm.username.trim(), loginForm.password);
            setAuthToken(result.token);
            user.value = result.user;
            loginForm.password = '';
            await refreshRooms();
        }
        catch (error) {
            setError(error);
        }
        finally {
            busy.value = false;
        }
    }
    async function logout() {
        await leaveCurrentRoomQuietly();
        roomSSE.disconnect();
        if (fallbackTimer)
            window.clearInterval(fallbackTimer);
        fallbackTimer = undefined;
        clearAuthToken();
        user.value = null;
        roomState.value = null;
        unsyncedRounds.value = [];
        localSettings.value.lastRoomId = '';
        saveLocalSettings(localSettings.value);
        view.value = 'lobby';
    }
    // ─── 房间列表 ───
    async function refreshRooms() {
        if (!user.value)
            return;
        try {
            rooms.value = (await fetchRooms()).rooms;
        }
        catch (error) {
            setError(error);
        }
    }
    // ─── 加入房间 ───
    function openJoin(room) {
        selectedRoom.value = room;
        joinForm.roomId = room.id;
        joinForm.password = roomPasswords[room.id] || '';
        view.value = 'join';
    }
    async function confirmSelectedJoin() {
        if (!selectedRoom.value)
            return;
        await join(selectedRoom.value.id, joinForm.password);
    }
    async function join(roomId, password = '', characterName = '', characterPersona = '') {
        if (!roomId.trim()) {
            setError('请输入房间号');
            return;
        }
        const cn = characterName || joinCharacterName.value.trim();
        const cp = characterPersona || joinCharacterPersona.value.trim();
        if (!cn) {
            setError('请填写你的角色名');
            return;
        }
        busy.value = true;
        try {
            const oldRoomId = roomState.value?.room.id || '';
            const result = await joinRoom(roomId.trim(), password, cn, cp);
            if (oldRoomId && oldRoomId !== result.room.id) {
                await leaveRoom(oldRoomId).catch(error => console.warn('[Online] leave previous room failed:', error));
            }
            await enterRoom(result.room.id);
        }
        catch (error) {
            setError(error);
        }
        finally {
            busy.value = false;
        }
    }
    // ─── 创建房间 ───
    function openCreate() {
        const character = captureCurrentCharacter();
        createForm.character_name = character.name;
        createForm.character_summary = character.summary;
        createForm.character_opening = character.opening;
        createForm.custom_opening = '';
        createForm.preset_name = getCurrentPresetNameSafe();
        createForm.title = character.name ? `${character.name} 的联机房间` : '新的联机房间';
        createForm.host_character_name = '';
        createForm.host_character_persona = '';
        requiredAssetsText.value = '';
        if (!localSettings.value.director.apiurl || !localSettings.value.director.model) {
            applyCurrentTavernApi(false);
        }
        view.value = 'create';
    }
    async function submitCreateRoom() {
        if (!createForm.character_card_link.trim()) {
            setError('请填写角色卡公开链接');
            return;
        }
        if (createForm.visibility === 'password' && !createForm.password.trim()) {
            setError('密码房间需要填写房间密码');
            return;
        }
        const payload = {
            title: createForm.title.trim() || '联机房间',
            visibility: createForm.visibility,
            password: createForm.password,
            character_name: createForm.character_name.trim(),
            character_summary: createForm.character_summary.trim(),
            character_opening: createForm.character_opening.trim(),
            custom_opening: createForm.custom_opening.trim(),
            character_card_link: createForm.character_card_link.trim(),
            preset_name: createForm.preset_name.trim(),
            required_assets: parseRequiredAssets(),
            per_player_words: Math.min(1000, Math.max(300, Number(createForm.per_player_words) || 1000)),
            per_player_min_words: Math.max(100, Math.min(5000, Number(createForm.per_player_min_words) || 700)),
            per_player_max_words: Math.max(100, Math.min(8000, Number(createForm.per_player_max_words) || 1000)),
            candidate_timeout_seconds: Math.max(30, Number(createForm.candidate_timeout_seconds) || 120),
            erase_on_close: createForm.erase_on_close,
            host_character_name: createForm.host_character_name.trim(),
            host_character_persona: createForm.host_character_persona.trim(),
        };
        busy.value = true;
        try {
            const oldRoomId = roomState.value?.room.id || '';
            const result = await createRoom(payload);
            if (oldRoomId && oldRoomId !== result.room.id) {
                await leaveRoom(oldRoomId).catch(error => console.warn('[Online] leave previous room failed:', error));
            }
            await enterRoom(result.room.id);
        }
        catch (error) {
            setError(error);
        }
        finally {
            busy.value = false;
        }
    }
    function parseRequiredAssets() {
        return requiredAssetsText.value
            .split(/\r?\n/)
            .map(line => line.trim())
            .filter(Boolean);
    }
    // ─── 导演 API 配置 ───
    function setDirectorModelsInternal(models) {
        directorModels.value = Array.from(new Set(models.map(model => model.trim()).filter(Boolean)));
        if (!localSettings.value.director.model && directorModels.value.length) {
            localSettings.value.director.model = directorModels.value[0];
        }
    }
    function applyCurrentTavernApi(showToast = true) {
        const snapshot = captureCurrentTavernApi(localSettings.value.director.key);
        localSettings.value.director = {
            ...localSettings.value.director,
            apiurl: snapshot.apiurl || localSettings.value.director.apiurl,
            key: snapshot.key || localSettings.value.director.key,
            model: snapshot.model || localSettings.value.director.model,
            source: snapshot.source || localSettings.value.director.source,
        };
        setDirectorModelsInternal(snapshot.models);
        directorModelHint.value = snapshot.models.length
            ? `已复制酒馆当前 API，并读取到 ${snapshot.models.length} 个模型`
            : '已复制酒馆当前 API；如果模型列表为空，请点击拉取模型';
        if (showToast)
            toastr.success('已复制酒馆当前 API 配置');
    }
    async function refreshDirectorModels() {
        directorModelBusy.value = true;
        directorModelHint.value = '';
        try {
            const models = await fetchDirectorModels(localSettings.value.director);
            setDirectorModelsInternal(models);
            directorModelHint.value = models.length ? `已拉取 ${models.length} 个模型` : '接口返回了空模型列表';
            if (models.length)
                toastr.success('模型列表已更新');
        }
        catch (error) {
            setError(error);
        }
        finally {
            directorModelBusy.value = false;
        }
    }
    // ─── 房间生命周期 ───
    async function enterRoom(roomId) {
        localSettings.value.lastRoomId = roomId;
        saveLocalSettings(localSettings.value);
        await loadRoomState(roomId);
        view.value = 'room';
        startSSE(roomId);
    }
    async function leaveCurrentRoomQuietly() {
        const roomId = roomState.value?.room.id;
        if (!roomId)
            return;
        try {
            await leaveRoom(roomId);
        }
        catch (error) {
            console.warn('[Online] leave room failed:', error);
        }
    }
    async function leaveRoomView() {
        if (unsyncedRounds.value.length > 0) {
            const doSync = confirm(`有 ${unsyncedRounds.value.length} 轮未同步到酒馆，是否在离开前同步？`);
            if (doSync)
                await syncToTavern();
        }
        await leaveCurrentRoomQuietly();
        disconnectAll();
        roomState.value = null;
        selectedRoom.value = null;
        unsyncedRounds.value = [];
        localSettings.value.lastRoomId = '';
        saveLocalSettings(localSettings.value);
        view.value = 'lobby';
        await refreshRooms();
    }
    async function exitPanel(onExit) {
        if (unsyncedRounds.value.length > 0) {
            const doSync = confirm(`有 ${unsyncedRounds.value.length} 轮未同步到酒馆，是否在关闭前同步？`);
            if (doSync)
                await syncToTavern();
        }
        await leaveCurrentRoomQuietly();
        disconnectAll();
        roomState.value = null;
        selectedRoom.value = null;
        unsyncedRounds.value = [];
        localSettings.value.lastRoomId = '';
        saveLocalSettings(localSettings.value);
        onExit();
    }
    function disconnectAll() {
        roomSSE.disconnect();
        if (fallbackTimer)
            window.clearInterval(fallbackTimer);
        fallbackTimer = undefined;
    }
    async function resumeLastRoom() {
        if (!user.value || !localSettings.value.lastRoomId)
            return;
        try {
            await enterRoom(localSettings.value.lastRoomId);
        }
        catch (error) {
            console.warn('[Online] resume last room failed:', error);
            localSettings.value.lastRoomId = '';
            saveLocalSettings(localSettings.value);
            roomState.value = null;
            view.value = 'lobby';
            await refreshRooms();
        }
    }
    // ─── SSE ───
    function startSSE(roomId) {
        if (fallbackTimer)
            window.clearInterval(fallbackTimer);
        fallbackTimer = undefined;
        setupSSEHandlers();
        roomSSE.connect(roomId);
        roomSSE.onStateChange(state => {
            sseStatus.value = state.status;
            if (state.status === 'reconnecting' && !fallbackTimer) {
                fallbackTimer = window.setInterval(async () => {
                    try {
                        await loadRoomState(roomId);
                    }
                    catch (error) {
                        console.warn('[Online] fallback poll failed:', error);
                        if (isRoomGoneError(error))
                            await handleRoomAccessLost();
                    }
                }, FALLBACK_POLL_INTERVAL_MS);
            }
            else if (state.status === 'connected' && fallbackTimer) {
                window.clearInterval(fallbackTimer);
                fallbackTimer = undefined;
            }
        });
    }
    function setupSSEHandlers() {
        roomSSE.on('full_state', (data) => {
            roomState.value = data;
            if (data.active_round?.status === 'integrating') {
                directorStream.value = data.active_round.assistant_message || directorStream.value;
            }
            else if (!data.active_round) {
                directorStream.value = '';
            }
        });
        roomSSE.on('chat_message', (msg) => {
            if (roomState.value) {
                roomState.value.chat_messages = [...roomState.value.chat_messages, msg];
            }
        });
        roomSSE.on('member_update', (data) => {
            if (roomState.value) {
                roomState.value.members = data.members;
                roomState.value.room = data.room;
            }
        });
        roomSSE.on('round_started', (round) => {
            if (roomState.value) {
                roomState.value.active_round = round;
                roundMessage.value = '';
                directorStream.value = '';
            }
        });
        roomSSE.on('round_input', (input) => {
            if (roomState.value?.active_round) {
                const inputs = roomState.value.active_round.inputs;
                const idx = inputs.findIndex((i) => i.user_id === input.user_id);
                if (idx >= 0) {
                    inputs[idx] = { ...inputs[idx], ...input };
                }
                else {
                    inputs.push(input);
                }
                roomState.value.active_round = { ...roomState.value.active_round, inputs: [...inputs] };
            }
        });
        roomSSE.on('candidate_ready', (data) => {
            if (roomState.value?.active_round) {
                const inputs = roomState.value.active_round.inputs;
                const idx = inputs.findIndex((i) => i.user_id === data.user_id);
                if (idx >= 0) {
                    inputs[idx] = { ...inputs[idx], ...data };
                    roomState.value.active_round = { ...roomState.value.active_round, inputs: [...inputs] };
                }
            }
        });
        roomSSE.on('director_stream', (data) => {
            directorStream.value = data.assistant_message || '';
            if (roomState.value?.active_round) {
                roomState.value.active_round = {
                    ...roomState.value.active_round,
                    status: 'integrating',
                    assistant_message: data.assistant_message || '',
                };
            }
        });
        roomSSE.on('round_finalized', (round) => {
            if (roomState.value) {
                roomState.value.active_round = null;
                roomState.value.finalized_rounds = [...roomState.value.finalized_rounds, round];
                directorStream.value = round.assistant_message || '';
                if (!unsyncedRounds.value.includes(round.id)) {
                    unsyncedRounds.value.push(round.id);
                }
                // 清理候选回复（30秒后服务器也会清）
                // 增加大总结计数器
                summaryCounter.value++;
                if (summaryCounter.value >= 10) {
                    summaryCounter.value = 0;
                    triggerSummary();
                }
            }
        });
        roomSSE.on('round_update', (round) => {
            if (roomState.value) {
                // reroll: 回退到 integrating
                if (round.status === 'integrating') {
                    roomState.value.active_round = round;
                    // 从 finalized_rounds 移除
                    roomState.value.finalized_rounds = roomState.value.finalized_rounds.filter(r => r.id !== round.id);
                    directorStream.value = round.assistant_message || '';
                }
            }
        });
        roomSSE.on('room_closed', () => {
            handleRoomAccessLost();
        });
    }
    function isRoomGoneError(error) {
        const message = error instanceof Error ? error.message : String(error);
        return message.includes('房间不存在') || message.includes('已关闭') || message.includes('还没有加入');
    }
    async function handleRoomAccessLost() {
        disconnectAll();
        roomState.value = null;
        unsyncedRounds.value = [];
        localSettings.value.lastRoomId = '';
        saveLocalSettings(localSettings.value);
        view.value = 'lobby';
        await refreshRooms();
        toastr.info('房间已关闭或已离开');
    }
    // ─── 数据加载 ───
    async function loadRoomState(roomId = roomState.value?.room.id) {
        if (!roomId)
            return;
        const state = await fetchRoomState(roomId);
        roomState.value = state;
        if (state.active_round?.status === 'integrating') {
            directorStream.value = state.active_round.assistant_message || directorStream.value;
        }
        else if (!state.active_round) {
            directorStream.value = '';
        }
    }
    // ─── 酒馆同步 ───
    async function syncToTavern() {
        const state = roomState.value;
        if (!state)
            return;
        if (state.room.custom_opening) {
            try {
                const synced = await syncCustomOpening(state.room);
                if (synced)
                    toastr.success('联机新开场白已同步到本地第一条消息');
            }
            catch (error) {
                console.warn('[Online] sync custom opening failed:', error);
                toastr.warning('联机新开场白同步失败');
            }
        }
        let syncCount = 0;
        for (const round of state.finalized_rounds) {
            try {
                const inserted = await insertFinalizedRound(state.room, round);
                if (inserted)
                    syncCount++;
            }
            catch (error) {
                console.warn('[Online] insert finalized round failed:', error);
            }
        }
        if (syncCount > 0) {
            toastr.success(`已同步 ${syncCount} 轮到酒馆楼层`);
            unsyncedRounds.value = [];
        }
        else {
            toastr.info('没有新的轮次需要同步');
        }
    }
    // ─── 聊天 ───
    async function sendChat() {
        const content = chatText.value.trim();
        const room = roomState.value?.room;
        if (!room || !content)
            return;
        chatText.value = '';
        try {
            await sendRoomChat(room.id, content);
        }
        catch (error) {
            setError(error);
        }
    }
    // ─── 准备 / 重Roll ───
    async function doToggleReady() {
        const room = roomState.value?.room;
        if (!room)
            return;
        try {
            await toggleReady(room.id);
        }
        catch (error) {
            setError(error);
        }
    }
    async function doRerollRound() {
        const round = roomState.value?.finalized_rounds.at(-1);
        if (!round)
            return;
        try {
            await rerollRound(round.id);
            toastr.success('已回退到整合状态，可以重新整合');
        }
        catch (error) {
            setError(error);
        }
    }
    // ─── 大总结 ───
    async function triggerSummary() {
        const state = roomState.value;
        if (!state || !isHost.value)
            return;
        try {
            toastr.info('正在生成大总结（每10轮自动触发）...');
            const summary = await generateSummary(state.room, state.finalized_rounds, localSettings.value.director);
            if (summary) {
                await sendRoomChat(state.room.id, `[大总结]\n${summary}`);
                toastr.success('大总结已发送到房间聊天');
            }
        }
        catch (error) {
            console.warn('[Online] summary generation failed:', error);
            toastr.warning('大总结生成失败');
        }
    }
    // ─── 回合操作 ───
    async function hostStartRound() {
        const room = roomState.value?.room;
        if (!room)
            return;
        try {
            await startRound(room.id);
            roundMessage.value = '';
            directorStream.value = '';
        }
        catch (error) {
            setError(error);
        }
    }
    async function submitTurn() {
        const room = roomState.value?.room;
        const round = activeRound.value;
        const message = roundMessage.value.trim();
        if (!room || !round || !message)
            return;
        try {
            await submitRoundInput(round.id, message);
            roundMessage.value = '';
            toastr.success('发言已提交，正在生成候选回复...');
        }
        catch (error) {
            setError(error);
            return;
        }
        candidateBusy.value = true;
        try {
            await generateAndSubmitCandidate(round.id, room, message);
            toastr.success('候选回复已提交');
        }
        catch (error) {
            console.warn('[Online] candidate generation failed:', error);
            toastr.warning('候选生成失败，可以点击重新生成');
        }
        finally {
            candidateBusy.value = false;
        }
    }
    async function retryCandidate() {
        const room = roomState.value?.room;
        const round = activeRound.value;
        const input = myInput.value;
        if (!room || !round || !input)
            return;
        candidateBusy.value = true;
        try {
            await generateAndSubmitCandidate(round.id, room, input.player_message);
            toastr.success('候选回复已重新提交');
        }
        catch (error) {
            setError(error);
        }
        finally {
            candidateBusy.value = false;
        }
    }
    async function generateAndSubmitCandidate(roundId, room, message) {
        const candidate = await generateCandidate(room, message);
        await submitCandidate(roundId, candidate);
    }
    async function hostIntegrate() {
        const state = roomState.value;
        const round = activeRound.value;
        if (!state || !round)
            return;
        if (!['collecting', 'integrating'].includes(round.status)) {
            setError('当前轮次已经结束');
            return;
        }
        if (round.inputs.length === 0) {
            setError('还没有玩家提交本轮发言');
            return;
        }
        integrationBusy.value = true;
        directorStream.value = '';
        let latestStream = '';
        let lastPushedStream = '';
        const pushStream = async (force = false) => {
            if (!force && latestStream === lastPushedStream)
                return;
            lastPushedStream = latestStream;
            try {
                await updateRoundStream(round.id, latestStream);
            }
            catch (error) {
                console.warn('[Online] stream sync failed:', error);
            }
        };
        const streamTimer = window.setInterval(() => {
            void pushStream();
        }, STREAM_PUSH_INTERVAL_MS);
        try {
            await updateRoundStream(round.id, '');
            await loadRoomState(state.room.id);
            const latestRound = activeRound.value || round;
            const members = roomState.value?.members;
            const userMessage = buildRoundUserMessage(state.room, latestRound, members);
            const assistantMessage = await runDirectorIntegration(state.room, latestRound, localSettings.value.director, text => {
                latestStream = text;
                directorStream.value = text;
            }, members);
            latestStream = assistantMessage;
            await pushStream(true);
            await finalizeRound(round.id, userMessage, assistantMessage);
            directorStream.value = assistantMessage;
            toastr.success('导演整合完成，最终回复已同步');
        }
        catch (error) {
            setError(error);
        }
        finally {
            window.clearInterval(streamTimer);
            integrationBusy.value = false;
        }
    }
    // ─── 导航 ───
    async function goLobby() {
        selectedRoom.value = null;
        view.value = 'lobby';
        await refreshRooms();
    }
    function goJoinFromFooter() {
        view.value = selectedRoom.value ? 'join' : 'lobby';
    }
    function goRoomFromFooter() {
        if (roomState.value) {
            view.value = 'room';
            return;
        }
        goLobby();
    }
    function copyRoomId() {
        const id = roomState.value?.room.id;
        if (!id)
            return;
        navigator.clipboard?.writeText(id).catch(() => undefined);
        toastr.success('房间号已复制');
    }
    function candidateStatusLabel(input) {
        if (input.status === 'candidate_ready')
            return '候选完成';
        if (candidateBusy.value && user.value && input.user_id === user.value.id)
            return '候选生成中';
        return '已提交';
    }
    // ─── 初始化 ───
    async function initialize() {
        try {
            await loadMe();
            await refreshRooms();
            if (user.value && localSettings.value.lastRoomId) {
                joinForm.roomId = localSettings.value.lastRoomId;
                await resumeLastRoom();
            }
        }
        finally {
            authReady.value = true;
        }
    }
    function cleanup() {
        disconnectAll();
    }
    return {
        // 状态
        view, user, rooms, roomState, selectedRoom, busy, authReady,
        loginForm, joinForm, joinCharacterName, joinCharacterPersona,
        roomPasswords, chatText, roundMessage,
        candidateBusy, integrationBusy, directorStream, directorModels,
        directorModelHint, directorModelBusy, localSettings, requiredAssetsText,
        sseStatus, unsyncedRounds, createForm, summaryCounter,
        // 计算属性
        isHost, activeRound, myInput, submittedCount, readyCount,
        pendingCandidateCount, visibleDirectorStream, canSubmitTurn,
        canRetryCandidate, canHostIntegrate, roomTargetWords, statusBannerText,
        allReady,
        // 方法
        doLogin, logout, refreshRooms, openJoin, confirmSelectedJoin, join,
        openCreate, submitCreateRoom, applyCurrentTavernApi, refreshDirectorModels,
        enterRoom, leaveRoomView, exitPanel, sendChat, hostStartRound,
        submitTurn, retryCandidate, hostIntegrate, goLobby, goJoinFromFooter,
        goRoomFromFooter, copyRoomId, candidateStatusLabel, syncToTavern,
        loadRoomState, initialize, cleanup, doToggleReady, doRerollRound,
        triggerSummary,
    };
});
