Ae,KAAQ,CACvB,oEAAqC,gBAAmB,CACxD,6BAAc,aAAc,CAAE,gBAAmB,CACjD,+BAAgB,YAAe,CAC/B,8BAAe,wBAA2B,CAC5C,CAEA,yBACE,8BAAe,YAAa,CAAE,0CAA6C,CAC3E,4BAAa,yBAA4B,CACzC,yBAAU,kBAAqB,CAC/B,yBAAU,OAAQ,CAAE,aAAgB,CACpC,mGAAoD,YAAe,CACnE,oEAAqC,aAAc,CAAE,aAAc,CAAE,oBAAuB,CAC5F,gCAAiB,YAAe,CAChC,2HAA4D,gBAAiB,CAAE,YAAe,CAC9F,kEAAmC,gCAAmC,CACtE,6BAAc,WAAY,CAAE,gBAAiB,CAAE,yBAA4B,CAC3E,kCAAmB,yBAA4B,CAC/C,kCAAmB,qBAAyB,CAC5C,+BAAgB,WAAc,CAG9B,8BAAe,aAAc,CAAE,aAAc,CAAE,oBAAuB,CACtE,yHAAsE,gBAAiB,CAAE,YAAe,CACxG,gCAAiB,uBAA0B,CAC3C,iCAAkB,YAAe,CACjC,8BAAe,wBAA2B,CAC1C,+BAAgB,uBAA0B,CAE1C,gCACE,YAAa,CACb,mCAAqC,CACrC,gCAAiC,CACjC,uBACF,CACA,uCACE,YAAa,CAAE,qBAAsB,CAAE,kBAAmB,CAAE,sBAAuB,CACnF,OAAQ,CAAE,QAAS,CAAE,sBAAuB,CAAE,kBAAmB,CAAE,cAAe,CAAE,aACtF,CACA,8CAA+B,mBAAoB,CAAE,eAAkB,CACzE","sourcesContent":["<script setup lang=\"ts\">\n/**\n * 酒馆联机脚本 — 主入口组件\n * 精简的路由壳，所有业务逻辑在 useOnlineStore 中，UI 拆分到子组件。\n */\nimport { useOnlineStore } from './stores/useOnline';\nimport ChatPanel from './components/ChatPanel.vue';\nimport MemberList from './components/MemberList.vue';\nimport RoundPanel from './components/RoundPanel.vue';\nimport TrimRulesConfig from './components/TrimRulesConfig.vue';\n\nconst props = defineProps<{ onExit: () => void; onMinimize: () => void }>();\nconst store = useOnlineStore();\n\n/** 手机端房间内 Tab */\nconst mobileRoomTab = ref<'round' | 'chat' | 'members' | 'settings'>('round');\n\nonMounted(() => store.initialize());\nonUnmounted(() => store.cleanup());\n</script>\n\n<template>\n  <div class=\"online-root\">\n    <!-- ─── 顶栏 ─── -->\n    <header class=\"topbar\">\n      <div class=\"brand\">\n        <span class=\"brand-mark\">OL</span>\n        <span>酒馆联机</span>\n        <span\n          v-if=\"store.roomState\"\n          class=\"sse-dot\"\n          :class=\"store.sseStatus\"\n          :title=\"store.sseStatus === 'connected' ? '实时连接' : store.sseStatus === 'reconnecting' ? '重连中' : '已断开'\"\n        />\n      </div>\n      <div v-if=\"store.user\" class=\"user-chip\">\n        <img v-if=\"store.user.avatar\" :src=\"store.user.avatar\" alt=\"\" />\n        <span>{{ store.user.display_name || store.user.username }}</span>\n      </div>\n      <button v-if=\"store.user && store.roomState && store.view !== 'room'\" class=\"ghost-btn nav-btn\" @click=\"store.view = 'room'\">房间</button>\n      <button v-if=\"store.user && store.view !== 'lobby'\" class=\"ghost-btn nav-btn\" @click=\"store.goLobby\">大厅</button>\n      <button v-if=\"store.user\" class=\"ghost-btn logout-btn\" @click=\"store.logout\">退出</button>\n      <button class=\"ghost-btn minimize-btn\" @click=\"props.onMinimize()\">最小化</button>\n      <button class=\"danger-btn\" @click=\"store.exitPanel(props.onExit)\">关闭</button>\n    </header>\n\n    <!-- ─── 加载中 ─── -->\n    <main v-if=\"!store.authReady\" class=\"login-screen\">\n      <section class=\"login-panel auth-loading\">\n        <h1>酒馆联机</h1>\n        <p>正在恢复登录状态</p>\n      </section>\n    </main>\n\n    <!-- ─── 登录 ─── -->\n    <main v-else-if=\"!store.user\" class=\"login-screen\">\n      <section class=\"login-panel\">\n        <h1>酒馆联机</h1>\n        <div class=\"field\">\n          <label>用户名</label>\n          <input v-model=\"store.loginForm.username\" autocomplete=\"username\" />\n        </div>\n        <div class=\"field\">\n          <label>密码</label>\n          <input v-model=\"store.loginForm.password\" type=\"password\" autocomplete=\"current-password\" @keydown.enter=\"store.doLogin\" />\n        </div>\n        <button class=\"primary-btn wide\" :disabled=\"store.busy\" @click=\"store.doLogin\">{{ store.busy ? '登录中' : '登录' }}</button>\n      </section>\n    </main>\n\n    <!-- ─── 大厅 ─── -->\n    <main v-else-if=\"store.view === 'lobby'\" class=\"lobby-layout\">\n      <section class=\"lobby-main\">\n        <div class=\"section-head\">\n          <div>\n            <h2>房间大厅</h2>\n            <p>{{ store.rooms.length }} 个可加入房间</p>\n          </div>\n          <div class=\"head-actions\">\n            <button v-if=\"store.roomState\" class=\"ghost-btn\" @click=\"store.view = 'room'\">回到房间</button>\n            <button class=\"ghost-btn\" @click=\"store.refreshRooms\">刷新</button>\n            <button class=\"primary-btn\" @click=\"store.openCreate\">创建房间</button>\n          </div>\n        </div>\n        <div class=\"rooms-grid\">\n          <article v-for=\"room in store.rooms\" :key=\"room.id\" class=\"room-card\">\n            <div class=\"room-card-head\">\n              <div>\n                <h3>{{ room.title }}</h3>\n                <span>{{ room.character_name || '未标注角色' }}</span>\n              </div>\n              <strong class=\"count-pill\">{{ room.member_count }}</strong>\n            </div>\n            <p class=\"room-summary\">{{ room.custom_opening || room.character_opening || room.character_summary || '无开场白' }}</p>\n            <div class=\"room-meta\">\n              <span>{{ room.visibility === 'password' ? '密码' : '公开' }}</span>\n              <span>{{ room.preset_name || '未标注预设' }}</span>\n            </div>\n            <input\n              v-if=\"room.visibility === 'password'\"\n              v-model=\"store.roomPasswords[room.id]\"\n              class=\"compact-input\"\n              type=\"password\"\n              placeholder=\"房间密码\"\n            />\n            <button class=\"primary-btn wide\" @click=\"store.openJoin(room)\">查看并加入</button>\n          </article>\n        </div>\n      </section>\n      <aside class=\"join-panel\">\n        <h2>按房间号加入</h2>\n        <div class=\"field\">\n          <label>房间号</label>\n          <input v-model=\"store.joinForm.roomId\" />\n        </div>\n        <div class=\"field\">\n          <label>密码</label>\n          <input v-model=\"store.joinForm.password\" type=\"password\" @keydown.enter=\"store.join(store.joinForm.roomId, store.joinForm.password)\" />\n        </div>\n        <button class=\"primary-btn wide\" @click=\"store.join(store.joinForm.roomId, store.joinForm.password)\">加入房间</button>\n      </aside>\n    </main>\n\n    <!-- ─── 加入确认 ─── -->\n    <main v-else-if=\"store.view === 'join' && store.selectedRoom\" class=\"join-detail-layout\">\n      <section class=\"join-hero\">\n        <div class=\"section-head\">\n          <div>\n            <h2>加入确认</h2>\n            <p>进入前先确认角色卡来源、预设和必需资源</p>\n          </div>\n          <button class=\"ghost-btn\" @click=\"store.view = 'lobby'\">返回</button>\n        </div>\n        <div class=\"character-strip\">\n          <div class=\"character-cover\">\n            <span>{{ store.selectedRoom.character_name.slice(0, 1) || '角' }}</span>\n          </div>\n          <div>\n            <h2>{{ store.selectedRoom.title }}</h2>\n            <p class=\"muted\">\n              角色：{{ store.selectedRoom.character_name || '未标注' }} · 房主：{{ store.selectedRoom.host_name }} ·\n              {{ store.selectedRoom.visibility === 'password' ? '密码房' : store.selectedRoom.visibility === 'unlisted' ? '不公开' : '公开房' }}\n            </p>\n            <p class=\"join-summary\">{{ store.selectedRoom.character_summary || '房主还没有填写角色摘要。' }}</p>\n          </div>\n        </div>\n        <div class=\"require-list\">\n          <a :href=\"store.selectedRoom.character_card_link\" target=\"_blank\">角色卡公开链接：{{ store.selectedRoom.character_card_link }}</a>\n          <div>推荐预设：{{ store.selectedRoom.preset_name || '未标注' }}</div>\n          <div>每人目标：{{ store.selectedRoom.per_player_min_words }}~{{ store.selectedRoom.per_player_max_words }} 字 · 候选等待：{{ store.selectedRoom.candidate_timeout_seconds }} 秒</div>\n        </div>\n      </section>\n      <aside class=\"join-confirm-panel\">\n        <div class=\"panel-box\">\n          <h3>加入房间</h3>\n          <div class=\"field\">\n            <label>你的角色名（必填）</label>\n            <input v-model=\"store.joinCharacterName\" placeholder=\"例如：明月\" />\n          </div>\n          <div class=\"field\">\n            <label>你的角色人设（选填）</label>\n            <textarea v-model=\"store.joinCharacterPersona\" rows=\"3\" placeholder=\"简要描述你要扮演的角色设定\" />\n          </div>\n          <div v-if=\"store.selectedRoom.visibility === 'password'\" class=\"field\">\n            <label>房间密码</label>\n            <input v-model=\"store.joinForm.password\" type=\"password\" @keydown.enter=\"store.confirmSelectedJoin\" />\n          </div>\n          <button class=\"primary-btn wide\" :disabled=\"store.busy\" @click=\"store.confirmSelectedJoin\">\n            {{ store.busy ? '加入中' : '确认加入' }}\n          </button>\n        </div>\n        <div class=\"panel-box\">\n          <h3>进入前检查</h3>\n          <p class=\"muted\">请确认本地酒馆已经选择对应角色卡和预设。加入后，每轮会消耗你自己的 API 生成候选回复。</p>\n        </div>\n      </aside>\n    </main>\n\n    <!-- ─── 创建房间 ─── -->\n    <main v-else-if=\"store.view === 'create'\" class=\"create-layout\">\n      <section class=\"create-panel\">\n        <div class=\"section-head\">\n          <div>\n            <h2>创建房间</h2>\n            <p>房主导演整合模式</p>\n          </div>\n          <button class=\"ghost-btn\" @click=\"store.view = 'lobby'\">返回</button>\n        </div>\n        <div class=\"form-grid\">\n          <div class=\"field\"><label>房间名</label><input v-model=\"store.createForm.title\" /></div>\n          <div class=\"field\">\n            <label>可见性</label>\n            <select v-model=\"store.createForm.visibility\">\n              <option value=\"public\">公开</option>\n              <option value=\"password\">密码</option>\n              <option value=\"unlisted\">不公开</option>\n            </select>\n          </div>\n          <div v-if=\"store.createForm.visibility === 'password'\" class=\"field\"><label>房间密码</label><input v-model=\"store.createForm.password\" type=\"password\" /></div>\n          <div class=\"field\"><label>每人最少字数</label><input v-model.number=\"store.createForm.per_player_min_words\" type=\"number\" min=\"100\" max=\"5000\" step=\"100\" /></div>\n          <div class=\"field\"><label>每人最多字数</label><input v-model.number=\"store.createForm.per_player_max_words\" type=\"number\" min=\"100\" max=\"8000\" step=\"100\" /></div>\n          <div class=\"field\"><label>候选等待秒数</label><input v-model.number=\"store.createForm.candidate_timeout_seconds\" type=\"number\" min=\"30\" step=\"10\" /></div>\n          <div class=\"field\"><label>当前角色</label><input v-model=\"store.createForm.character_name\" /></div>\n          <div class=\"field\"><label>推荐预设</label><input v-model=\"store.createForm.preset_name\" /></div>\n          <div class=\"field span-2\"><label>你的角色名（房主）</label><input v-model=\"store.createForm.host_character_name\" placeholder=\"你要扮演的角色名\" /></div>\n          <div class=\"field span-2\"><label>你的角色人设（房主，选填）</label><textarea v-model=\"store.createForm.host_character_persona\" rows=\"2\" placeholder=\"简要描述你要扮演的角色设定\" /></div>\n          <div class=\"field span-2\"><label>角色卡公开链接</label><input v-model=\"store.createForm.character_card_link\" placeholder=\"Discord 帖子或公开发布页\" /></div>\n          <div class=\"field span-2\"><label>角色简介</label><textarea v-model=\"store.createForm.character_summary\" rows=\"4\" /></div>\n          <div class=\"field span-2\"><label>需要下载的内容</label><textarea v-model=\"store.requiredAssetsText\" rows=\"3\" placeholder=\"每行一个链接或说明\" /></div>\n          <label class=\"check-row span-2\"><input v-model=\"store.createForm.erase_on_close\" type=\"checkbox\" /><span>关闭房间时清空正文记录</span></label>\n        </div>\n        <div class=\"director-box\">\n          <h3>房主导演 API</h3>\n          <div class=\"director-actions\">\n            <button class=\"ghost-btn\" @click=\"store.applyCurrentTavernApi()\">复制酒馆当前 API</button>\n            <button class=\"ghost-btn\" :disabled=\"store.directorModelBusy\" @click=\"store.refreshDirectorModels\">{{ store.directorModelBusy ? '拉取中' : '拉取模型' }}</button>\n          </div>\n          <div class=\"form-grid\">\n            <div class=\"field\">\n              <label>接口来源</label>\n              <select v-model=\"store.localSettings.director.source\">\n     