ore.localSettings.trimRules.length\" class=\"trim-empty\">\n      暂无裁剪规则，点击\"添加规则\"开始配置\n    </div>\n\n    <div v-for=\"(rule, idx) in store.localSettings.trimRules\" :key=\"idx\" class=\"trim-rule\">\n      <div class=\"rule-row\">\n        <div class=\"field rule-mode\">\n          <label>模式</label>\n          <select v-model=\"rule.mode\">\n            <option value=\"keep\">保留</option>\n            <option value=\"remove\">删除</option>\n          </select>\n        </div>\n        <div class=\"field rule-tag\">\n          <label>开始标签</label>\n          <input v-model=\"rule.startTag\" :placeholder=\"placeholders[rule.mode]?.start\" />\n        </div>\n        <div class=\"field rule-tag\">\n          <label>结束标签</label>\n          <input v-model=\"rule.endTag\" :placeholder=\"placeholders[rule.mode]?.end\" />\n        </div>\n        <button class=\"ghost-btn rule-del\" title=\"删除此规则\" @click=\"removeRule(idx)\">✕</button>\n      </div>\n      <p class=\"rule-hint\">\n        {{ rule.mode === 'keep'\n          ? '只保留开始标签与结束标签之间的内容，其余部分丢弃'\n          : '删除开始标签与结束标签之间的内容（含标签本身），保留其余部分'\n        }}\n      </p>\n    </div>\n  </div>\n</template>\n\n<style scoped>\n.trim-config {\n  padding: 14px;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: var(--panel-2);\n}\n\n.trim-header {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 12px;\n  margin-bottom: 12px;\n}\n\n.trim-header h3 {\n  margin: 0;\n  font-size: 14px;\n}\n\n.trim-desc {\n  margin: 4px 0 0;\n  color: var(--muted);\n  font-size: 12px;\n}\n\n.trim-empty {\n  padding: 16px;\n  text-align: center;\n  color: var(--muted);\n  font-size: 13px;\n  border: 1px dashed var(--line);\n  border-radius: 7px;\n}\n\n.trim-rule {\n  padding: 12px;\n  border: 1px solid var(--line);\n  border-radius: 7px;\n  background: var(--panel);\n  margin-bottom: 10px;\n}\n\n.trim-rule:last-child {\n  margin-bottom: 0;\n}\n\n.rule-row {\n  display: flex;\n  align-items: flex-end;\n  gap: 10px;\n}\n\n.rule-mode {\n  flex: 0 0 90px;\n}\n\n.rule-tag {\n  flex: 1;\n  min-width: 0;\n}\n\n.rule-del {\n  flex-shrink: 0;\n  width: 34px;\n  height: 34px;\n  padding: 0;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  color: var(--danger);\n  font-size: 14px;\n}\n\n.rule-hint {\n  margin: 8px 0 0;\n  color: var(--muted);\n  font-size: 11px;\n  line-height: 1.4;\n}\n\n/* 复用外部定义的按钮、表单样式 */\n.field {\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n}\n\n.field label {\n  color: var(--muted);\n  font-size: 11px;\n}\n\ninput, select {\n  width: 100%;\n  box-sizing: border-box;\n  height: 34px;\n  padding: 0 9px;\n  border: 1px solid var(--line);\n  border-radius: 6px;\n  background: rgba(0,0,0,0.16);\n  color: var(--text);\n  outline: none;\n  font: inherit;\n  font-size: 13px;\n}\n\ninput:focus, select:focus {\n  border-color: rgba(86,194,168,0.55);\n}\n\ninput::placeholder {\n  color: var(--muted);\n  opacity: 0.5;\n}\n\n.ghost-btn {\n  height: 34px;\n  padding: 0 13px;\n  border: 0;\n  border-radius: 7px;\n  cursor: pointer;\n  font: inherit;\n  color: var(--text);\n  background: var(--soft);\n  white-space: nowrap;\n}\n\n.ghost-btn:hover {\n  background: rgba(255,255,255,0.13);\n}\n\n@media (max-width: 680px) {\n  .rule-row {\n    flex-wrap: wrap;\n  }\n\n  .rule-mode {\n    flex: 0 0 100%;\n  }\n\n  .rule-tag {\n    flex: 1 1 calc(50% - 27px);\n  }\n}\n</style>\n"],"sourceRoot":""}]);
