e:none;font:inherit}textarea[data-v-36ad96ff]:focus{border-color:rgba(86,194,168,0.55)}textarea[data-v-36ad96ff]:disabled{opacity:0.5}.story-timeline[data-v-36ad96ff]{margin-bottom:16px;border:1px solid var(--line);border-radius:8px;background:var(--panel);max-height:400px;overflow-y:auto;scroll-behavior:smooth;transition:max-height 0.3s ease}.story-timeline.expanded[data-v-36ad96ff]{max-height:none}.story-entry[data-v-36ad96ff]{padding:12px 14px;border-bottom:1px solid var(--line)}.story-entry[data-v-36ad96ff]:last-child{border-bottom:none}.story-label[data-v-36ad96ff]{font-size:12px;font-weight:600;margin-bottom:6px}.story-entry.opening .story-label[data-v-36ad96ff]{color:var(--accent-2)}.story-entry.user-entry .story-label[data-v-36ad96ff]{color:var(--accent-2)}.story-entry.assistant-entry .story-label[data-v-36ad96ff]{color:var(--accent)}.story-entry.live[data-v-36ad96ff]{background:rgba(86,194,168,0.04);animation:story-pulse-36ad96ff 2s ease-in-out infinite}@keyframes story-pulse-36ad96ff{0%,100%{opacity:1}50%{opacity:0.8}}.story-text[data-v-36ad96ff]{white-space:pre-wrap;line-height:1.65;color:rgba(255,255,255,0.82);font-size:13.5px}.story-entry.opening .story-text[data-v-36ad96ff]{color:rgba(255,255,255,0.7)}.director-stream[data-v-36ad96ff]{margin-top:12px;padding:12px;border:1px solid rgba(86,194,168,0.28);border-radius:8px;background:rgba(86,194,168,0.06)}.director-stream h3[data-v-36ad96ff]{margin:0 0 8px;font-size:14px}.director-stream p[data-v-36ad96ff]{margin:0;white-space:pre-wrap;line-height:1.55}.primary-btn[data-v-36ad96ff],.ghost-btn[data-v-36ad96ff]{height:34px;padding:0 13px;border:0;border-radius:7px;cursor:pointer;font:inherit}.primary-btn[data-v-36ad96ff]{color:#061310;background:var(--accent);font-weight:700}.primary-btn[data-v-36ad96ff]:disabled{cursor:not-allowed;opacity:0.55}.ghost-btn[data-v-36ad96ff]{color:var(--text);background:var(--soft)}.ghost-btn[data-v-36ad96ff]:hover{background:rgba(255,255,255,0.13)}.wide[data-v-36ad96ff]{width: