s/useOnline';\nimport { applyTrimRules } from '../types';\nimport StatusBanner from './StatusBanner.vue';\n\nconst store = useOnlineStore();\n\n/** 房间内 Tab 导航（手机端用） */\nconst roomTab = defineModel<string>('roomTab', { default: 'round' });\n\n/** 对文本应用当前裁剪规则 */\nfunction trimmed(text: string): string {\n  return applyTrimRules(text, store.localSettings.trimRules);\n}\n</script>\n\n<template>\n  <section class=\"round-panel\">\n    <StatusBanner />\n\n    <!-- 剧情正文区：开场白 + 已完成轮次的最终正文 -->\n    <div v-if=\"store.roomState\" class=\"story-timeline\" :class=\"{ expanded: !store.activeRound }\">\n      <!-- 开场白 -->\n      <div class=\"story-entry opening\">\n        <div class=\"story-label\">开场白</div>\n        <div class=\"story-text\">{{ store.roomState.room.custom_opening || store.roomState.room.character_opening || '没有读取到角色卡开场白。' }}</div>\n      </div>\n\n      <!-- 已完成轮次的正文 -->\n      <template v-for=\"round in store.roomState.finalized_rounds\" :key=\"round.id\">\n        <div class=\"story-entry user-entry\">\n          <div class=\"story-label\">第 {{ round.round_no }} 轮 · 玩家发言</div>\n          <div class=\"story-text\">{{ round.user_message }}</div>\n        </div>\n        <div class=\"story-entry assistant-entry\">\n          <div class=\"story-label\">第 {{ round.round_no }} 轮 · {{ store.roomState.room.character_name || 'AI' }} 回复</div>\n          <div class=\"story-text\">{{ trimmed(round.assistant_message) }}</div>\n        </div>\n      </template>\n\n      <!-- 当前轮次导演输出（实时） -->\n      <div v-if=\"store.visibleDirectorStream && store.activeRound\" class=\"story-entry assistant-entry live\">\n        <div class=\"story-label\">第 {{ store.activeRound.round_no }} 轮 · 导演整合中...</div>\n        <div class=\"story-text\">{{ store.visibleDirectorStream }}</div>\n      </div>\n    </div>\n\n    <div class=\"section-head\">\n      <div>\n        <h2>{{ store.activeRound ? `第 ${store.activeRound.round_no} 轮` : '等待开轮' }}</h2>\n        <p v-if=\"store.activeRound\">\n          已提交 {{ store.submittedCount }} 人，候选完成 {{ store.readyCount }} 人，待生成 {{ store.pendingCandidateCount }} 人\n        </p>\n        <p v-else>房主开启下一轮后开始提交 · 本房间最多 8 人</p>\n      </div>\n      <div class=\"head-actions\">\n        <button class=\"ghost-btn\" @click=\"store.loadRoomState()\">刷新</button>\n        <button\n          v-if=\"store.isHost && !store.activeRound\"\n          class=\"primary-btn\"\n          :disabled=\"!store.allReady && (store.roomState?.members.length || 0) > 1\"\n          :title=\"!store.allReady ? '等待所有玩家准备' : ''\"\n          @click=\"store.hostStartRound\"\n        >\n          开始新一轮{{ !store.allReady && (store.roomState?.members.length || 0) > 1 ? '（等待准备）' : '' }}\n        </button>\n        <button\n          v-if=\"store.isHost && store.activeRound\"\n          class=\"primary-btn\"\n          :disabled=\"!store.canHostIntegrate\"\n          @click=\"store.hostIntegrate\"\n        >\n          {{ store.integrationBusy ? '整合中' : store.activeRound.status === 'integrating' ? '接手整合' : '开始整合' }}\n        </button>\n        <button\n          v-if=\"store.isHost && !store.activeRound && store.roomState?.finalized_rounds.length\"\n          class=\"ghost-btn\"\n          @click=\"store.doRerollRound\"\n        >\n          重Roll上轮\n        </button>\n      </div>\n    </div>\n\n    <div class=\"round-status\">\n      <div class=\"status-box\">\n        <strong>{{ store.submittedCount }}</strong>\n        <span>已提交</span>\n      </div>\n      <div class=\"status-box\">\n        <strong>{{ store.readyCount }}</strong>\n        <span>候选完成</span>\n      </div>\n      <div class=\"status-box\">\n        <strong>{{ store.roomTargetWords }}</strong>\n        <span>目标总字数</span>\n      </div>\n    </div>\n\n    <!-- 回合进行中 -->\n    <div v-if=\"store.activeRound\" class=\"turn-box\">\n      <div class=\"candidate-list\">\n        <article v-for=\"input in store.activeRound.inputs\" :key=\"input.user_id\" class=\"candidate-card\">\n          <header>\n            <strong>{{ input.display_name }}</strong>\n            <span class=\"candidate-status\" :class=\"input.status\">\n              {{ store.candidateStatusLabel(input) }}\n            </span>\n          </header>\n          <p class=\"player-msg\">{{ input.player_message }}</p>\n          <blockquote v-if=\"input.candidate_reply\" class=\"candidate-reply\">{{ trimmed(input.candidate_reply) }}</blockquote>\n        </article>\n      </div>\n\n      <div class=\"submit-area\">\n        <textarea\n          v-model=\"store.roundMessage\"\n          rows=\"5\"\n          :disabled=\"store.activeRound.status !== 'collecting' || store.candidateBusy || !!store.myInput\"\n          placeholder=\"输入本轮发言；提交后会生成你的本地候选回复\"\n        />\n        <button\n          class=\"primary-btn wide\"\n          :disabled=\"!(store.canSubmitTurn || store.canRetryCandidate)\"\n          @click=\"store.myInput ? store.retryCandidate() : store.submitTurn()\"\n        >\n          {{\n            store.candidateBusy ? '生成候选中...'\n            : store.canRetryCandidate ? '重新生成候选'\n            : store.myInput ? '本轮已提交，等待整合'\n            : '提交并生成候选'\n          }}\n        </button>\n      </div>\n    </div>\n\n    <!-- 导演输出（非流式时的状态提示） -->\n    <div v-if=\"!store.visibleDirectorStream && store.activeRound?.status === 'integrating'\" class=\"director-stream live-empty\">\n      <h3>导演输出</h3>\n      <p>导演已经开始整合，第一段内容出现后会自动同步到剧情正文区。</p>\n    </div>\n  </section>\n</template>\n\n<style scoped>\n.round-panel {\n  overflow: auto;\n  padding: 16px;\n  background: var(--bg);\n  min-height: 0;\n}\n\n.section-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  margin-bottom: 14px;\n}\n\n.section-head h2 {\n  margin: 0;\n  font-size: 18px;\n}\n\n.section-head p {\n  margin: 4px 0 0;\n  color: var(--muted);\n  font-size: 12px;\n}\n\n.head-actions {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.round-status {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 10px;\n  margin-bottom: 14px;\n}\n\n.status-box {\n  padding: 12px;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: var(--panel);\n}\n\n.status-box strong {\n  display: block;\n  margin-bottom: 3px;\n  font-size: 18px;\n}\n\n.status-box span {\n  color: var(--muted);\n  font-size: 12px;\n}\n\n.turn-box {\n  display: grid;\n  gap: 12px;\n}\n\n.candidate-list {\n  display: grid;\n  align-content: start;\n  gap: 10px;\n  overflow: auto;\n  max-height: 400px;\n}\n\n.candidate-card {\n  padding: 12px;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: var(--panel);\n}\n\n.candidate-card header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px;\n  margin-bottom: 8px;\n}\n\n.candidate-status {\n  font-size: 12px;\n  color: var(--muted);\n}\n\n.candidate-status.candidate_ready {\n  color: var(--accent);\n}\n\n.candidate-status.submitted {\n  color: #e0bd69;\n}\n\n.player-msg {\n  margin: 0;\n  white-space: pre-wrap;\n  line-height: 1.55;\n  color: var(--muted);\n}\n\n.candidate-reply {\n  margin: 10px 0 0;\n  padding: 10px;\n  border-left: 3px solid rgba(86, 194, 168, 0.65);\n  color: rgba(255, 255, 255, 0.72);\n  background: rgba(86, 194, 168, 0.08);\n  white-space: pre-wrap;\n  line-height: 1.55;\n}\n\n.submit-area {\n  display: grid;\n  gap: 10px;\n}\n\ntextarea {\n  width: 100%;\n  box-sizing: border-box;\n  resize: none;\n  padding: 10px;\n  line-height: 1.5;\n  border: 1px solid var(--line);\n  border-radius: 7px;\n  background: rgba(0, 0, 0, 0.16);\n  color: var(--text);\n  outline: none;\n  font: inherit;\n}\n\ntextarea:focus {\n  border-color: rgba(86, 194, 168, 0.55);\n}\n\ntextarea:disabled {\n  opacity: 0.5;\n}\n\n/* 剧情正文区 */\n.story-timeline {\n  margin-bottom: 16px;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: var(--panel);\n  max-height: 400px;\n  overflow-y: auto;\n  scroll-behavior: smooth;\n  transition: max-height 0.3s ease;\n}\n\n/* 没有活跃回合时，正文区展开占满可用空间 */\n.story-timeline.expanded {\n  max-height: none;\n}\n\n.story-entry {\n  padding: 12px 14px;\n  border-bottom: 1px solid var(--line);\n}\n\n.story-entry:last-child {\n  border-bottom: none;\n}\n\n.story-label {\n  font-size: 12px;\n  font-weight: 600;\n  margin-bottom: 6px;\n}\n\n.story-entry.opening .story-label {\n  color: var(--accent-2);\n}\n\n.story-entry.user-entry .story-label {\n  color: var(--accent-2);\n}\n\n.story-entry.assistant-entry .story-label {\n  color: var(--accent);\n}\n\n.story-entry.live {\n  background: rgba(86, 194, 168, 0.04);\n  animation: story-pulse 2s ease-in-out infinite;\n}\n\n@keyframes story-pulse {\n  0%, 100% { opacity: 1; }\n  50% { opacity: 0.8; }\n}\n\n.story-text {\n  white-space: pre-wrap;\n  line-height: 1.65;\n  color: rgba(255, 255, 255, 0.82);\n  font-size: 13.5px;\n}\n\n.story-entry.opening .story-text {\n  color: rgba(255, 255, 255, 0.7);\n}\n\n/* 导演状态提示 */\n.director-stream {\n  margin-top: 12px;\n  padding: 12px;\n  border: 1px solid rgba(86, 194, 168, 0.28);\n  border-radius: 8px;\n  background: rgba(86, 194, 168, 0.06);\n}\n\n.director-stream h3 {\n  margin: 0 0 8px;\n  font-size: 14px;\n}\n\n.director-stream p {\n  margin: 0;\n  white-space: pre-wrap;\n  line-height: 1.55;\n}\n\n/* 按钮 */\n.primary-btn,\n.ghost-btn {\n  height: 34px;\n  padding: 0 13px;\n  border: 0;\n  border-radius: 7px;\n  cursor: pointer;\n  font: inherit;\n}\n\n.primary-btn {\n  color: #061310;\n  background: var(--accent);\n  font-weight: 700;\n}\n\n.primary-btn:disabled {\n  cursor: not-allowed;\n  opacity: 0.55;\n}\n\n.ghost-btn {\n  color: var(--text);\n  background: var(--soft);\n}\n\n.ghost-btn:hover {\n  background: rgba(255, 255, 255, 0.13);\n}\n\n.wide {\n  width: 100%;\n}\n\n@media (max-width: 680px) {\n  .round-panel {\n    padding: 12px;\n    overflow: visible;\n  }\n\n  .round-status {\n    grid-template-columns: 1fr;\n  }\n\n  .candidate-list {\n    max-height: none;\n    overflow: visible;\n  }\n}\n</style>\n"],"sourceRoot":""}]);
