/**
 * SSE 客户端连接管理器
 *
 * 连接到后端的 SSE 事件流，接收实时推送事件。
 * 支持自动重连（指数退避）和 fallback 到低频轮询。
 */

import { API_BASE, getAuthToken } from './types';

export type SSEEventHandler = (data: any) => void;

/** SSE 支持的事件类型 */
export type SSEEventType =
  | 'full_state'       // 连接时推送的完整状态
  | 'chat_message'     // 新聊天消息
  | 'member_update'    // 成员列表变化（加入/离开/房主变更）
  | 'round_started'    // 新一轮开始
  | 'round_input'      // 玩家提交发言
  | 'candidate_ready'  // 候选回复完成
  | 'director_stream'  // 导演流式输出
  | 'round_finalized'  // 轮次完成
  | 'round_update'     // 回合状态更新
  | 'room_closed';     // 房间关闭

export interface SSEConnectionState {
  status: 'disconnected' | 'connecting' | 'connected' | 'reconnecting';
  reconnectAttempt: number;
  lastEventAt: number;
}

const MAX_RECONNECT_DELAY_MS = 30_000;
const BASE_RECONNECT_DELAY_MS = 1_000;

export class RoomSSEClient {
  private eventSource: EventSource | null = null;
  private handlers: Map<string, Set<SSEEventHandler>> = new Map();
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private roomId: string = '';
  private _state: SSEConnectionState = {
    status: 'disconnected',
    reconnectAttempt: 0,
    lastEventAt: 0,
  };
  private stateListeners: Set<(state: SSEConnectionState) => void> = new Set();

  get state(): SSEConnectionState {
    return { ...this._state };
  }

  /** 监听连接状态变化 */
  onStateChange(listener: (state: SSEConnectionState) => void): () => void {
    this.stateListeners.add(listener);
    return () => this.stateListeners.delete(listener);
  }

  private updateState(partial: Partial<SSEConnectionState>): void {
    Object.assign(this._state, partial);
    for (const listener of this.stateListeners) {
      try {
        listener(this.state);
      } catch (e) {
        console.warn('[SSE] state listener error:', e);
      }
    }
  }

  /** 注册事件处理器 */
  on(event: SSEEventType | string, handler: SSEEventHandler): () => void {
    let handlers = this.handlers.get(event);
    if (!handlers) {
      handlers = new Set();
      this.handlers.set(event, handlers);
    }
    handlers.add(handler);

    // 如果 EventSource 已连接，动态添加监听
    if (this.eventSource && this.eventSource.readyState !== EventSource.CLOSED) {
      this.eventSource.addEventListener(event, ((e: MessageEvent) => {
        try {
          handler(JSON.parse(e.data));
        } catch (err) {
          console.warn(`[SSE] handler error for "${event}":`, err);
        }
      }) as EventListener);
    }

    return () => {
      handlers?.delete(handler);
      if (handlers?.size === 0) {
        this.handlers.delete(event);
      }
    };
  }

  /** 连接到房间的 SSE 事件流 */
  connect(roomId: string): void {
    this.disconnect();
    this.roomId = roomId;
    this.updateState({ status: 'connecting', reconnectAttempt: 0 });
    this.createEventSource();
  }

  /** 断开连接 */
  disconnect(): void {
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
    if (this.eventSource) {
      this.eventSource.close();
      this.eventSource = null;
    }
    this.roomId = '';
    this.updateState({ status: 'disconnected', reconnectAttempt: 0 });
  }

  /** 是否已连接 */
  get connected(): boolean {
    return this._state.status === 'connected';
  }

  private createEventSource(): void {
    const token = getAuthToken();
    if (!token || !this.roomId) {
      this.updateState({ status: 'disconnected' });
      return;
    }

    const url = `${API_BASE}/api/online/rooms/${encodeURIComponent(this.roomId)}/events?token=${encodeURIComponent(token)}`;

    try {
      const es = new EventSource(url);
      this.eventSource = es;

      es.onopen = () => {
        console.info('[SSE] connected to room:', this.roomId);
        this.updateState({
          status: 'connected',
          reconnectAttempt: 0,
          lastEventAt: Date.now(),
        });
      };

      es.onerror = () => {
        console.warn('[SSE] connection error, will reconnect');
        es.close();
        this.eventSource = null;
        this.scheduleReconnect();
      };

      // 注册所有已注册的事件处理器
      for (const [event, handlers] of this.handlers.entries()) {
        for (const handler of handlers) {
          es.addEventListener(event, ((e: MessageEvent) => {
            this.updateState({ lastEventAt: Date.now() });
            try {
              handler(JSON.parse(e.data));
            } catch (err) {
              console.warn(`[SSE] handler error for "${event}":`, err);
            }
          }) as EventListener);
        }
      }
    } catch (err) {
      console.error('[SSE] failed to create EventSource:', err);
      this.scheduleReconnect();
    }
  }

  private scheduleReconnect(): void {
    if (!this.roomId) return; // 已经 disconnect 了

    const attempt = this._state.reconnectAttempt + 1;
    const delay = Math.min(
      MAX_RECONNECT_DELAY_MS,
      BASE_RECONNECT_DELAY_MS * Math.pow(2, Math.min(attempt - 1, 10)),
    );

    console.info(`[SSE] reconnecting in ${delay}ms (attempt ${attempt})`);
    this.updateState({ status: 'reconnecting', reconnectAttempt: attempt });

    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = null;
      if (this.roomId) {
        this.createEventSource();
      }
    }, delay);
  }
}

/** 全局单例 */
export const roomSSE = new RoomSSEClient();
