export const API_BASE = 'https://sanmingyue.zeabur.app';
export const AUTH_TOKEN_KEY = 'workshop-auth-token';
export const ONLINE_LOCAL_KEY = 'tavern-online-settings';
export const INSERTED_ROUNDS_KEY = 'tavern-online-inserted-rounds';
export const OPENING_SYNC_KEY = 'tavern-online-opening-syncs';

export interface TrimRule {
  mode: 'keep' | 'remove';
  startTag: string;
  endTag: string;
}

