export interface DirectorConfig {
  apiurl: string;
  key: string;
  model: string;
  source: string;
  max_tokens: number | 'same_as_preset' | 'unset';
  temperature: number | 'same_as_preset' | 'unset';
}

export interface LocalSettings {
  director: DirectorConfig;
  lastRoomId: string;
  trimRules: TrimRule[];
}

export const DEFAULT_DIRECTOR_CONFIG: DirectorConfig = {
  apiurl: '',
  key: '',
  model: '',
  source: 'openai',
  max_tokens: 'same_as_preset',
  temperature: 'same_as_preset',
};

export const DEFAULT_LOCAL_SETTINGS: LocalSettings = {
  director: DEFAULT_DIRECTOR_CONFIG,
  lastRoomId: '',
  trimRules: [],
};

export function getAuthToken(): string | null {
  try {
    return window.parent.localStorage.getItem(AUTH_TOKEN_KEY);
  } catch {
    return null;
  }
}

export function setAuthToken(token: string): void {
  try {
    window.parent.localStorage.setItem(AUTH_TOKEN_KEY, token);
  } catch {
    // ignore
  }
}

export function clearAuthToken(): void {
  try {
    window.parent.localStorage.removeItem(AUTH_TOKEN_KEY);
  } catch {
    // ignore
  }
}

export function readLocalSettings(): LocalSettings {
  try {
    const raw = window.parent.localStorage.getItem(ONLINE_LOCAL_KEY);
    if (!raw) return DEFAULT_LOCAL_SETTINGS;
    const parsed = JSON.parse(raw) as Partial<LocalSettings>;
    return {
      director: { ...DEFAULT_DIRECTOR_CONFIG, ...(parsed.director || {}) },
      lastRoomId: parsed.lastRoomId || '',
      trimRules: Array.isArray(parsed.trimRules) ? parsed.trimRules : [],
    };
  } catch {
    return DEFAULT_LOCAL_SETTINGS;
  }
}

function escapeRegex(str: string): string {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

export function applyTrimRules(text: string, rules: TrimRule[]): string {
  if (!rules.length || !text) return text;
  let result = text;
  for (const rule of rules) {
    if (!rule.startTag || !rule.endTag) continue;
    if (rule.mode === 'keep') {
      const regex = new RegExp(
        `${escapeRegex(rule.startTag)}([\\s\\S]*?)${escapeRegex(rule.endTag)}`,
        'g',
      );
      const matches = [...result.matchAll(regex)].map(m => m[1].trim());
      if (matches.length) result = matches.join('\n\n');
    } else {
      const regex = new RegExp(
        `${escapeRegex(rule.startTag)}[\\s\\S]*?${escapeRegex(rule.endTag)}`,
        'g',
      );
      result = result.replace(regex, '').trim();
    }
  }
  return result;
}

export function saveLocalSettings(settings: LocalSettings): void {
  try {
    window.parent.localStorage.setItem(ONLINE_LOCAL_KEY, JSON.stringify(settings));
  } catch {
    // ignore
  }
}
