export async function joinRoom(roomId: string, password: string = '', characterName: string = '', characterPersona: string = ''): Promise<{ room: OnlineRoom }> {
  return request(`/api/online/rooms/${encodeURIComponent(roomId)}/join`, {
    method: 'POST',
    body: JSON.stringify({ password, character_name: characterName, character_persona: characterPersona }),
  });
}

