function parentDocument() {
    try {
        return window.parent.document;
    }
    catch {
        return null;
    }
}
function elementValue(id) {
    const element = parentDocument()?.getElementById(id);
    return element?.value?.trim() || '';
}
function selectOptions(id) {
    const select = parentDocument()?.getElementById(id);
    if (!select)
        return [];
    return Array.from(select.options)
        .map(option => option.value || option.textContent?.trim() || '')
        .map(value => value.trim())
        .filter(value => value && value !== 'None' && !value.includes('连接到API'));
}
function normalizeDirectorSource(source) {
    return source === 'custom' ? 'openai' : source || 'openai';
}
function normalizeModelBaseUrl(rawUrl) {
    return rawUrl
        .trim()
        .replace(/\/+$/, '')
        .replace(/\/(?:chat\/completions|responses|completions|messages)$/i, '')
        .replace(/\/models$/i, '');
}
function withApiKeyQuery(rawUrl, key) {
    if (!key)
        return rawUrl;
    try {
        const url = new URL(rawUrl);
        if (!url.searchParams.has('key')) {
            url.searchParams.set('key', key);
        }
        return url.toString();
    }
    catch {
        return rawUrl;
    }
}
function buildModelRequests(rawUrl, key, source) {
    const baseUrl = normalizeModelBaseUrl(rawUrl);
    const sourceName = normalizeDirectorSource(source).toLowerCase();
    const jsonHeaders = {
        Accept: 'application/json',
        'Content-Type': 'application/json',
    };
    const bearerHeaders = key
        ? { ...jsonHeaders, Authorization: `Bearer ${key}` }
        : jsonHeaders;
    if (sourceName === 'claude') {
        return [{
                url: `${baseUrl}/models`,
                headers: {
                    ...jsonHeaders,
                    ...(key ? { 'x-api-key': key } : {}),
                    'anthropic-version': '2023-06-01',
                },
            }];
    }
    if (sourceName === 'google' || sourceName === 'gemini' || sourceName === 'makersuite') {
        return [{ url: withApiKeyQuery(`${baseUrl}/models`, key), headers: jsonHeaders }];
    }
    if (sourceName === 'deepseek') {
        const rootBase = baseUrl.replace(/\/v1$/i, '');
        return [
            { url: `${baseUrl}/models`, headers: bearerHeaders },
            { url: `${rootBase}/v1/models`, headers: bearerHeaders },
        ];
    }
    return [{ url: `${baseUrl}/models`, headers: bearerHeaders }];
}
function extractModelNames(payload) {
    const data = payload;
    const candidates = [data?.data, data?.models, data?.model_list, payload];
    const names = candidates
        .filter(Array.isArray)
        .flatMap((items) => items
        .map(item => {
        if (typeof item === 'string')
            return item;
        const model = item;
        const value = model.id ?? model.name ?? model.model;
        return typeof value === 'string' ? value.replace(/^models\//, '') : '';
    })
        .filter(Boolean));
    return Array.from(new Set(names));
}
async function readModelApiError(response) {
    const status = `${response.status} ${response.statusText || '请求失败'}`;
    try {
        const payload = await response.clone().json();
        const apiMessage = payload?.error?.message ?? payload?.message ?? payload?.error;
        return typeof apiMessage === 'string' ? `${status}: ${apiMessage}` : status;
    }
    catch {
        try {
            const text = await response.text();
            return text ? `${status}: ${text.slice(0, 240)}` : status;
        }
        catch {
            return status;
        }
    }
}
async function fetchModelsDirectly(director) {
    const apiurl = director.apiurl.trim() || DEFAULT_APIURL_BY_SOURCE[director.source] || '';
    if (!apiurl)
        throw new Error('请先填写或复制 API 地址');
    const errors = [];
    for (const request of buildModelRequests(apiurl, director.key.trim(), director.source)) {
        try {
            const response = await fetch(request.url, {
                method: 'GET',
                headers: request.headers,
                cache: 'no-store',
            });
            if (!response.ok) {
                errors.push(await readModelApiError(response));
                continue;
            }
            const models = extractModelNames(await response.json());
            if (models.length)
                return models;
            errors.push('响应中没有可用模型');
        }
        catch (error) {
            errors.push(error instanceof Error ? error.message : String(error));
        }
    }
    throw new Error(errors.join('；') || '模型端点不可用');
}
export function captureCurrentTavernApi(existingKey = '') {
    const tavernSource = elementValue('chat_completion_source') || 'custom';
    const modelSelectId = MODEL_SELECT_BY_SOURCE[tavernSource];
    const modelFromSelect = modelSelectId ? elementValue(modelSelectId) : '';
    const modelFromInput = tavernSource === 'custom' ? elementValue('custom_model_id') : '';
    const apiurl = tavernSource === 'custom'
        ? elementValue('custom_api_url_text')
        : DEFAULT_APIURL_BY_SOURCE[tavernSource] || elementValue('openai_reverse_proxy');
    const keyInputId = KEY_INPUT_BY_SOURCE[tavernSource];
    const key = keyInputId ? elementValue(keyInputId) : '';
    return {
        apiurl,
        key: key || existingKey,
        model: modelFromSelect || modelFromInput,
        source: normalizeDirectorSource(tavernSource),
        models: modelSelectId ? selectOptions(modelSelectId) : [],
    };
}
export async function fetchDirectorModels(director) {
    const source = normalizeDirectorSource(director.source);
    const apiurl = director.apiurl.trim() || DEFAULT_APIURL_BY_SOURCE[source] || '';
    const fallbackDeepSeekModels = ['deepseek-chat', 'deepseek-reasoner', 'deepseek-coder'];
    if (!apiurl) {
        if (source === 'deepseek')
            return fallbackDeepSeekModels;
        throw new Error('请先填写或复制 API 地址');
    }
    const modelConfig = { ...director, apiurl, source };
    if (source !== 'deepseek') {
        try {
            const models = await getModelList({ apiurl, key: director.key || undefined });
            if (models.length)
                return models.filter(Boolean);
            console.warn('[Online] 酒馆助手 getModelList 返回空模型列表，改用直接请求');
        }
        catch (error) {
            console.warn('[Online] 酒馆助手 getModelList 调用失败，改用直接请求:', error);
        }
    }
    try {
        return await fetchModelsDirectly(modelConfig);
    }
    catch (error) {
        if (source === 'deepseek') {
            console.warn('[Online] DeepSeek 模型拉取失败，使用默认模型列表:', error);
            return fallbackDeepSeekModels;
        }
        throw error;
    }
}
