function textSignature(text) {
    let hash = 0;
    for (let i = 0; i < text.length; i++) {
        hash = Math.imul(31, hash) + text.charCodeAt(i) | 0;
    }
    return `${text.length}:${(hash >>> 0).toString(36)}`;
}
export async function syncCustomOpening(room) {
    const opening = room.custom_opening.trim();
    if (!opening)
        return false;
    const syncKey = `${room.id}:${textSignature(opening)}`;
    const synced = readOpeningSyncs();
    if (synced[syncKey])
        return false;
    const firstWithSwipes = getChatMessages(0, { include_swipes: true })[0];
    const firstMessage = getChatMessages(0)[0];
    const sourceMessage = firstMessage?.message || firstWithSwipes?.swipes?.[firstWithSwipes.swipe_id || 0] || room.character_opening || '';
    if (!firstWithSwipes && !firstMessage) {
        await createChatMessages([{
                role: 'assistant',
                name: room.character_name || 'AI',
                message: opening,
                data: { tavern_online: { room_id: room.id, source: 'custom_opening' } },
            }], { insert_before: 0, refresh: 'all' });
        synced[syncKey] = true;
        writeOpeningSyncs(synced);
        return true;
    }
    const swipes = [...(firstWithSwipes?.swipes?.length ? firstWithSwipes.swipes : [sourceMessage])];
    const existingIndex = swipes.findIndex(swipe => swipe.trim() === opening);
    const swipeId = existingIndex >= 0 ? existingIndex : swipes.length;
    if (existingIndex < 0) {
        swipes.push(opening);
    }
    const swipesData = [...(firstWithSwipes?.swipes_data || [])];
    const swipesInfo = [...(firstWithSwipes?.swipes_info || [])];
    while (swipesData.length < swipes.length)
        swipesData.push({});
    while (swipesInfo.length < swipes.length)
        swipesInfo.push({});
    swipesData[swipeId] = {
        ...swipesData[swipeId],
        tavern_online: { room_id: room.id, source: 'custom_opening' },
    };
    await setChatMessages([{
            message_id: 0,
            swipes,
            swipes_data: swipesData,
            swipes_info: swipesInfo,
            swipe_id: swipeId,
        }], { refresh: 'all' });
    synced[syncKey] = true;
    writeOpeningSyncs(synced);
    return true;
}
