function enabledPresetPrompts() {
    try {
        const preset = getPreset('in_use');
        const prompts = [];
        const usedBuiltin = new Set();
        for (const prompt of preset.prompts) {
            if (!prompt.enabled)
                continue;
            if (isPresetPlaceholderPrompt(prompt)) {
                const builtin = PLACEHOLDER_TO_BUILTIN[prompt.id];
                if (builtin && !usedBuiltin.has(builtin)) {
                    prompts.push(builtin);
                    usedBuiltin.add(builtin);
                }
                continue;
            }
            if ((isPresetNormalPrompt(prompt) || isPresetSystemPrompt(prompt)) && prompt.content?.trim()) {
                prompts.push({
                    role: prompt.role || 'system',
                    content: prompt.content,
                });
            }
        }
        if (!usedBuiltin.has('chat_history')) {
            prompts.push('chat_history');
        }
        return prompts;
    }
    catch (error) {
        console.warn('[Online] 读取当前预设失败，使用默认内置顺序:', error);
        return [...builtin_prompt_default_order];
    }
}
