export async function runDirectorIntegration(room, round, director, onStream, members) {
    if (!director.apiurl.trim() || !director.model.trim()) {
        throw new Error('请先复制/填写房主导演 API，并从模型列表选择模型');
    }
    const generationId = `online-director-${round.id}-${Date.now()}`;
    const listener = eventOn(iframe_events.STREAM_TOKEN_RECEIVED_FULLY, (text, eventGenerationId) => {
        if (eventGenerationId === generationId) {
            onStream(text);
        }
    });
    try {
        return await generateRaw({
            generation_id: generationId,
            should_stream: true,
            should_silence: true,
            custom_api: {
                apiurl: director.apiurl,
                key: director.key || undefined,
                model: director.model,
                source: normalizeDirectorSource(director.source),
                max_tokens: director.max_tokens,
                temperature: director.temperature,
            },
            ordered_prompts: [
                ...enabledPresetPrompts(),
                {
                    role: 'system',
                    content: '当前任务是多人 AIRP 的导演整合。你只输出最终剧情正文。',
                },
                {
                    role: 'user',
                    content: buildDirectorInstruction(room, round.inputs, members),
                },
            ],
        });
    }
    finally {
        listener.stop();
    }
}
